请对以下 case 进行三维加权评分。

=== case_id ===
Case-23-countdown-004

=== 用户原始指令 (query.txt) ===
帮我弄个生日倒计时吧 上面有个按钮 点下数字会变 也能跳日历 能读日程

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个生日倒计时吧 上面有个按钮 点下数字会变 也能跳日历 能读日程",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "evt-birthday-2026"
        }
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "生日日程的唯一标识，用于打开对应日历详情。",
              "sampleValue": "evt-birthday-2026"
            },
            "title": {
              "type": "string",
              "description": "生日相关日程标题。",
              "sampleValue": "妈妈生日"
            },
            "description": {
              "type": "string",
              "description": "生日倒计时天数数字，用于主倒计时显示。",
              "sampleValue": "12"
            },
            "dtStart": {
              "type": "string",
              "description": "生日日程日期展示文本。",
              "sampleValue": "7月21日"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，适合用于生日倒计时、日程管理和跳转日历入口。"
    }
  ]
}

